package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArrayUtils_lastIndexOf_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;







    @Test
    public void testLastIndexOf_StartIndexOutOfBoundsHigh() {
        // If startIndex >= length, it should be clamped to length - 1
        boolean[] array = {true, false, true};
        // Clamped to index 2. Last index of 'true' is 2.
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 5));
        // Clamped to index 2. Last index of 'false' is 1.
        assertEquals(1, ArrayUtils.lastIndexOf(array, false, 5));
    }














}

